    },
    {
      "activity_id": "A4",
      "activity_name": "Windows Acceptance Testing CI",
      "activity_description": "Provision a Windows image in EC2, configure the environment, and set up a CI build to run acceptance test coverage in the Windows environment.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "A5",
      "activity_name": "Spark Streaming Integration",
      "activity_description": "Implement Spark Streaming as data processors in XD, providing implementations using Java/Java Lambdas and Scala to demonstrate capabilities.",
