    },
    {
      "activity_id": "A6",
      "activity_name": "Reference Guide Copyright Update",
      "activity_description": "Update the copyright message in the reference guide source files to include 2015 and regenerate the PDF.",
      "most_likely_effort": 0.5
    },
    {
      "activity_id": "A7",
      "activity_name": "Kafka GA Upgrade",
      "activity_description": "Backport Kafka XD changes to Spring Integration (SI) Kafka, then upgrade to the Kafka SI GA release, ensuring all tests pass.",
